12	 * registration date — supplied in the request or defaulted by {@link BuildOwner} — a
13	 * Saturday rolls forward two days and a Sunday one day to the following Monday, stored
14	 * back on the owner. Weekdays are left unchanged. The rule extends to public holidays:
15	 * when the adjusted date lands on a listed public holiday, it rolls forward to the next
16	 * non-holiday business day. Everything derived from the registration date (the
17	 * membership number's year segment, the daily create-limit) reads it back off the owner,
18	 * so it sees the adjusted date.
19	 */
20	public class NormalizeOwnerRegistrationDate {
21	
22	    /** Fixed public-holiday calendar: dates that are never valid registration days. */
23	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
24	            LocalDate.of(2026, 1, 1),
25	            LocalDate.of(2026, 1, 26),
26	            LocalDate.of(2026, 4, 25),
27	            LocalDate.of(2026, 12, 25),
28	            LocalDate.of(2026, 12, 28));
29	
30	    public void service(@Val Owner owner) {
31	        LocalDate registrationDate = owner.getRegistrationDate();
32	        while (!isBusinessDay(registrationDate)) {
33	            registrationDate = registrationDate.plusDays(1);
34	        }
35	        owner.setRegistrationDate(registrationDate);
36	    }
37	
38	    private static boolean isBusinessDay(LocalDate date) {
39	        DayOfWeek day = date.getDayOfWeek();
40	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY
41	                && !PUBLIC_HOLIDAYS.contains(date);
42	    }
43	}
