7	
8	/**
9	 * Assigns the owner's {@code membershipPoints} and derived numeric
10	 * {@code membershipLevel} on create. Points start at 0 and accumulate: add 2 when an
11	 * email address is present, add 1 when {@code namesakeCount} is 0, add 2 when the owner
12	 * belongs to a household of three or more members, and add 3 for tenure of more than
13	 * one elapsed fiscal year (the fiscal year starts on 1 July). The points then map to a
14	 * level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more
15	 * points. A newly created owner has zero tenure (its registration date is the server
16	 * date), so a new owner never earns the tenure points.
17	 * Runs after {@code namesakeCount} and {@code householdSize} have been counted and
18	 * before the owner is saved, so both values are fixed at creation time.
19	 */
20	public class AssignMembershipLevel {
21	
22	    private static final int TENURE_FISCAL_YEARS_FOR_POINTS = 1;
23	
24	    public void service(@Val Owner owner) {
25	        int points = 0;
26	        String email = owner.getEmail();
27	        if (email != null && !email.isBlank()) {
28	            points += 2;
29	        }
30	        Integer namesakeCount = owner.getNamesakeCount();
31	        if (namesakeCount != null && namesakeCount == 0) {
32	            points += 1;
33	        }
34	        Integer householdSize = owner.getHouseholdSize();
35	        if (householdSize != null && householdSize >= 3) {
36	            points += 2;
37	        }
38	        if (tenureFiscalYears(owner) > TENURE_FISCAL_YEARS_FOR_POINTS) {
39	            points += 3;
40	        }
41	        owner.setMembershipPoints(points);
42	        owner.setMembershipLevel(levelForPoints(points));
43	    }
44	
45	    private static int levelForPoints(int points) {
46	        if (points >= 6) {
47	            return 4;
48	        }
49	        if (points >= 4) {
50	            return 3;
51	        }
52	        if (points >= 2) {
53	            return 2;
54	        }
55	        return 1;
56	    }
57	
58	    private static int tenureFiscalYears(Owner owner) {
59	        LocalDate registrationDate = owner.getRegistrationDate();
60	        if (registrationDate == null) {
61	            return 0;
62	        }
63	        return OwnerFiscalYear.elapsedFiscalYears(registrationDate, LocalDate.now());
64	    }
65	}
