29	        String lastName = owner.getLastName();
30	        String postcode = owner.getPostcode();
31	        String telephone = normalizedTelephone(owner);
32	
33	        owner.setPossibleDuplicate(false);
34	        owner.setPossibleDuplicateOf(null);
35	
36	        if (Boolean.TRUE.equals(sharesHousehold)) {
37	            // Declared household member: expected to share a household, not a suspected duplicate.
38	            return;
39	        }
40	
41	        if (lastName == null || postcode == null) {
42	            return;
43	        }
44	
45	        Integer matchId = null;
46	        for (Owner existing : ownerRepository.findAll()) {
47	            if (existing.getId() == null || existing.getId().equals(owner.getId())) {
48	                continue;
49	            }
50	            if (Boolean.TRUE.equals(existing.getDeleted())) {
51	                // A soft-deleted owner is not a duplicate signal.
52	                continue;
53	            }
54	            if (!lastName.equalsIgnoreCase(existing.getLastName())) {
55	                continue;
56	            }
57	            if (!postcode.equals(existing.getPostcode())) {
58	                continue;
59	            }
60	            // A different telephone is what distinguishes a soft match from a hard
61	            // (identityKey) duplicate, which has already been rejected upstream. Compare
62	            // through the same normalization as the hard check so the two can't drift.
63	            if (telephone.equals(normalizedTelephone(existing))) {
64	                continue;
65	            }
66	            if (matchId == null || existing.getId() < matchId) {
67	                matchId = existing.getId();
68	            }
69	        }
70	
71	        if (matchId != null) {
72	            owner.setPossibleDuplicate(true);
73	            owner.setPossibleDuplicateOf(matchId);
74	        }
75	    }
