84	        String telephone = OwnerTelephones.toE164(owner.getTelephone());
85	        if (telephone == null) {
86	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
87	        }
88	        return telephone;
89	    }
90	}
